import { Component, OnInit } from '@angular/core';

interface WordExample {
  word: string;
  syllables: string[];
  sounds: string[];
  meaning: string;
}

@Component({
  selector: 'app-syllable-breaker',
  templateUrl: './syllable-breaker.component.html',
  styleUrls: ['./syllable-breaker.component.scss']
})
export class SyllableBreakerComponent implements OnInit {

  inputWord = 'آموزگار';
  resultSyllables: string[] = [];
  resultSounds: string[] = [];

  // دیتابیس کلمات پرکاربرد کتاب فارسی کلاس اول
  dictionary: Record<string, { syllables: string[]; sounds: string[]; meaning: string }> = {
    'آب': { syllables: ['آب'], sounds: ['آ', 'ب'], meaning: 'مایه حیات' },
    'بابا': { syllables: ['با', 'با'], sounds: ['ب', 'ا', 'ب', 'ا'], meaning: 'پدر مهربان' },
    'نان': { syllables: ['نان'], sounds: ['ن', 'ا', 'ن'], meaning: 'برکت سفره' },
    'باران': { syllables: ['با', 'ران'], sounds: ['ب', 'ا', 'ر', 'ا', 'ن'], meaning: 'باران رحمت' },
    'مادر': { syllables: ['ما', 'در'], sounds: ['م', 'ا', 'د', 'ر'], meaning: 'مادر دلسوز' },
    'ایران': { syllables: ['ای', 'ران'], sounds: ['ا', 'ی', 'ر', 'ا', 'ن'], meaning: 'میهن عزیز ما' },
    'آموزگار': { syllables: ['آ', 'موز', 'گار'], sounds: ['آ', 'م', 'و', 'ز', 'گ', 'ا', 'ر'], meaning: 'معلم دانا' },
    'کتاب': { syllables: ['کِ', 'تاب'], sounds: ['ک', 'ِ', 'ت', 'ا', 'ب'], meaning: 'یار مهربان' },
    'مدرسه': { syllables: ['مد', 'رَ', 'سه'], sounds: ['م', 'د', 'ر', 'َ', 'س', 'ه'], meaning: 'خانه دوم دانش‌آموز' },
    'مداد': { syllables: ['مِ', 'داد'], sounds: ['م', 'ِ', 'د', 'ا', 'د'], meaning: 'ابزار نوشتن' },
    'انار': { syllables: ['اَ', 'نار'], sounds: ['ا', 'َ', 'ن', 'ا', 'ر'], meaning: 'میوه بهشتی' },
    'درخت': { syllables: ['دِ', 'رَخت'], sounds: ['د', 'ِ', 'ر', 'َ', 'خ', 'ت'], meaning: 'سرسبز و زیبا' },
    'خورشید': { syllables: ['خور', 'شید'], sounds: ['خ', 'و', 'ر', 'ش', 'ی', 'د'], meaning: 'چراغ آسمان' },
    'مهربان': { syllables: ['مِه', 'رَ', 'بان'], sounds: ['م', 'ِ', 'ه', 'ر', 'َ', 'ب', 'ا', 'ن'], meaning: 'خوش‌قلب' },
    'ستاره': { syllables: ['سِ', 'تا', 'ره'], sounds: ['س', 'ِ', 'ت', 'ا', 'ر', 'ه'], meaning: 'درخشان در شب' },
    'بادام': { syllables: ['با', 'دام'], sounds: ['ب', 'ا', 'د', 'ا', 'م'], meaning: 'مغز خوشمزه' },
    'سیب': { syllables: ['سیب'], sounds: ['س', 'ی', 'ب'], meaning: 'میوه سلامت' }
  };

  presetWords = Object.keys(this.dictionary);

  // کوئیز بخش‌کردن با دست زدن
  quizWord = 'ایران';
  quizTargetCount = 2;
  quizScore = 0;
  quizFeedback = '';
  quizAnswered = false;

  ngOnInit(): void {
    this.analyzeWord();
    this.newQuiz();
  }

  analyzeWord(): void {
    const clean = this.inputWord ? this.inputWord.trim() : '';
    if (!clean) {
      this.resultSyllables = [];
      this.resultSounds = [];
      return;
    }

    if (this.dictionary[clean]) {
      this.resultSyllables = this.dictionary[clean].syllables;
      this.resultSounds = this.dictionary[clean].sounds;
    } else {
      // تجزیه خودکار الگوریتمی اولیه برای کلمات جدید
      this.resultSyllables = this.autoSyllabify(clean);
      this.resultSounds = clean.split('').filter(ch => ch !== ' ');
    }
  }

  selectPreset(w: string): void {
    this.inputWord = w;
    this.analyzeWord();
  }

  // الگوریتم ساده تخمین هجای کلمات فارسی پایه اول
  private autoSyllabify(word: string): string[] {
    const vowels = ['ا', 'آ', 'و', 'ی', 'َ', 'ِ', 'ُ'];
    const parts: string[] = [];
    let current = '';

    for (let i = 0; i < word.length; i++) {
      current += word[i];
      if (vowels.includes(word[i]) && current.length >= 2 && i < word.length - 1) {
        // اگر بعد از این یک صامت و مصوت دیگر است
        if (i + 2 < word.length && vowels.includes(word[i + 2])) {
          parts.push(current);
          current = '';
        }
      }
    }
    if (current) {
      parts.push(current);
    }
    return parts.length > 0 ? parts : [word];
  }

  // کوئیز شمارش بخش‌ها
  newQuiz(): void {
    this.quizAnswered = false;
    this.quizFeedback = '';
    const keys = Object.keys(this.dictionary);
    const randomKey = keys[Math.floor(Math.random() * keys.length)];
    this.quizWord = randomKey;
    this.quizTargetCount = this.dictionary[randomKey].syllables.length;
  }

  answerQuiz(count: number): void {
    if (this.quizAnswered) { return; }
    this.quizAnswered = true;
    if (count === this.quizTargetCount) {
      this.quizFeedback = 'correct';
      this.quizScore += 10;
    } else {
      this.quizFeedback = 'wrong';
    }
  }
}
